import ch.jalu.configme.configurationdata.CommentsConfiguration;
import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class CommentsConfigurationTest {

    @Test
    public void setCommentSingleLineTest() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        String path = "config.test";
        String comment = "This is a test comment.";

        commentsConfiguration.setComment(path, comment);

        Map<String, List<String>> result = commentsConfiguration.getAllComments();

        assertEquals(1, result.size());
        assertEquals(Collections.singletonList(comment), result.get(path));
    }

    @Test
    public void setCommentMultipleLinesTest() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        String path = "config.test";
        String[] comments = {"This is the first line of comment.", "This is the second line."};

        commentsConfiguration.setComment(path, comments);

        Map<String, List<String>> result = commentsConfiguration.getAllComments();

        assertEquals(1, result.size());
        assertEquals(Arrays.asList(comments), result.get(path));
    }

    @Test
    public void getAllCommentsEmptyTest() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();

        Map<String, List<String>> result = commentsConfiguration.getAllComments();

        assertTrue(result.isEmpty());
    }

    @Test
    public void getAllCommentsFilledTest() {
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("config.test", Arrays.asList("comment1", "comment2"));

        CommentsConfiguration commentsConfiguration = new CommentsConfiguration(comments);

        Map<String, List<String>> result = commentsConfiguration.getAllComments();

        assertEquals(comments, result);
    }
}
